const emailData = $('Extract Email Fields').item.json;
const qdrantResult = $input.item.json;

let memoryContext = 'No previous conversations found with this sender.';
let previousConversations = [];

try {
  if (qdrantResult && qdrantResult.result && qdrantResult.result.length > 0) {
    previousConversations = qdrantResult.result.map(r => r.payload);
    memoryContext = previousConversations
      .map((conv, i) => `--- Past Conversation ${i + 1} ---\nDate: ${conv.timestamp || 'Unknown'}\nSubject: ${conv.subject || 'Unknown'}\nCategory: ${conv.category || 'Unknown'}\nSummary: ${conv.body_summary || 'No summary'}\nOur Reply: ${conv.reply_sent || 'No reply recorded'}\n`)
      .join('\n');
  }
} catch (e) {
  memoryContext = 'Memory retrieval error. Proceeding without context.';
}

return [{
  json: {
    ...emailData,
    memoryContext,
    previousConversationCount: previousConversations.length,
    isReturningContact: previousConversations.length > 0,
    processingId: 'email_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9)
  }
}];

// Build the complete Ollama request payload as a clean JSON string.
// This avoids all n8n expression-in-body issues.
const d = $input.item.json;

const prompt = `You are a professional executive email assistant.

## PREVIOUS CONVERSATIONS
${d.memoryContext}

## CURRENT EMAIL
From: ${d.senderName} <${d.senderEmail}>
Date: ${d.receivedDate}
Subject: ${d.subject}

${d.emailBody}

## TASK
Output ONLY valid JSON — no markdown, no explanation:
{
  "intent": "what the sender wants",
  "category": "Job Application|HR|Support|Customer Inquiry|Personal|Business|Meeting Request|Newsletter|Spam|Other",
  "urgency_score": 5,
  "urgency_reason": "brief reason",
  "reply_style": "formal|casual|technical|empathetic",
  "draft_reply": "complete reply text",
  "reply_subject": "reply subject line",
  "summary": "one sentence summary",
  "tasks": ["action item 1"],
  "spam_score": 0.05,
  "spam_reason": "brief reason",
  "follow_up_needed": false,
  "follow_up_date": null,
  "language_detected": "en",
  "is_meeting_request": false,
  "meeting_proposed_time": null,
  "suggested_actions": ["next action"]
}
Rules: never invent facts; spam_score>0.7 sets category to Spam; output JSON only.`;

const payload = {
  model: 'llama3.1',
  prompt: prompt,
  stream: false,
  options: { temperature: 0.3, num_predict: 2048 }
};

return [{ json: { ...d, ollamaPayload: JSON.stringify(payload) } }];

const inputData = $('Build Memory Context').item.json;
const ollamaResponse = $input.item.json;

let ai = {};
try {
  const raw = ollamaResponse.response || '';
  const match = raw.match(/{[\s\S]*}/);
  if (match) { ai = JSON.parse(match[0]); }
  else { throw new Error('No JSON in response'); }
} catch (e) {
  ai = {
    intent: 'Could not parse AI response',
    category: 'Other',
    urgency_score: 5,
    urgency_reason: 'Default',
    reply_style: 'formal',
    draft_reply: 'Dear ' + inputData.senderName + ',\n\nThank you for your email. I will respond shortly.\n\nBest regards',
    reply_subject: 'Re: ' + inputData.subject,
    summary: 'Email received',
    tasks: [],
    spam_score: 0.0,
    spam_reason: 'Could not analyse',
    follow_up_needed: false,
    follow_up_date: null,
    language_detected: 'en',
    is_meeting_request: false,
    meeting_proposed_time: null,
    suggested_actions: ['Review manually']
  };
}

return [{
  json: {
    ...inputData,
    ai: {
      intent: ai.intent || 'Unknown',
      category: ai.category || 'Other',
      urgencyScore: ai.urgency_score || 5,
      urgencyReason: ai.urgency_reason || '',
      replyStyle: ai.reply_style || 'formal',
      draftReply: ai.draft_reply || '',
      replySubject: ai.reply_subject || ('Re: ' + inputData.subject),
      summary: ai.summary || '',
      tasks: ai.tasks || [],
      spamScore: ai.spam_score || 0.0,
      spamReason: ai.spam_reason || '',
      followUpNeeded: ai.follow_up_needed || false,
      followUpDate: ai.follow_up_date || null,
      languageDetected: ai.language_detected || 'en',
      isMeetingRequest: ai.is_meeting_request || false,
      meetingProposedTime: ai.meeting_proposed_time || null,
      suggestedActions: ai.suggested_actions || []
    },
    isSpam: (ai.spam_score || 0.0) > 0.7
  }
}];

const data = $input.item.json;
const now = new Date();
const dateStr = now.toISOString().replace('T', ' ').substring(0, 19);
const dateFile = now.toISOString().replace(/[:.]/g, '-').substring(0, 19);

const markdownLog = `# SPAM — Email Skipped\n\n**Date:** ${dateStr}  \n**From:** ${data.senderName} <${data.senderEmail}>  \n**Subject:** ${data.subject}  \n**Spam Score:** ${((data.ai || {}).spamScore * 100 || 0).toFixed(0)}%  \n**Reason:** ${(data.ai || {}).spamReason || 'Classified as spam'}  \n**Action:** No reply sent.  \n\n---\n*AI Email Auto Responder*\n`;

return [{
  json: {
    ...data,
    markdownLog,
    logFilePath: '/home/node/logs/' + dateFile + '_SPAM_' + data.senderEmail.replace(/[@.]/g, '_') + '.md',
    action: 'SPAM_SKIPPED'
  }
}];

const fs = require('fs');
const path = require('path');
const data = $input.item.json;
try {
  const dir = path.dirname(data.logFilePath);
  if (!fs.existsSync(dir)) { fs.mkdirSync(dir, { recursive: true }); }
  fs.writeFileSync(data.logFilePath, data.markdownLog, 'utf8');
} catch(e) { console.error('Spam log write error:', e.message); }
return [{ json: { ...data, spamLogWritten: true } }];

const data = $input.item.json;
const executionId = $execution.id;
const approveUrl = 'http://localhost:5678/webhook-waiting/' + executionId + '?action=approve';
const rejectUrl  = 'http://localhost:5678/webhook-waiting/' + executionId + '?action=reject';

const urgencyLabel = data.ai.urgencyScore >= 8 ? '🔴 HIGH' : data.ai.urgencyScore >= 5 ? '🟡 MEDIUM' : '🟢 LOW';

const approvalEmailBody = `AI EMAIL AUTO RESPONDER — APPROVAL REQUEST
==========================================

From    : ${data.senderName} <${data.senderEmail}>
Subject : ${data.subject}
Category: ${data.ai.category}
Urgency : ${urgencyLabel} (${data.ai.urgencyScore}/10)

SUMMARY
-------
${data.ai.summary}

AI DRAFT REPLY
--------------
Subject: ${data.ai.replySubject}

${data.ai.draftReply}

==========================================
✅ APPROVE (sends the reply above):
${approveUrl}

❌ REJECT (discards draft):
${rejectUrl}
==========================================
Processing ID: ${data.processingId}`;

return [{ json: { ...data, approvalEmailBody, approveUrl, rejectUrl } }];

const data = $('Parse AI Response').item.json;
const now = new Date();
const dateStr = now.toISOString().replace('T', ' ').substring(0, 19);
const dateFile = now.toISOString().replace(/[:.]/g, '-').substring(0, 19);

const urgencyEmoji = data.ai.urgencyScore >= 8 ? '🔴' : data.ai.urgencyScore >= 5 ? '🟡' : '🟢';
const taskList = (data.ai.tasks || []).map(t => '- [ ] ' + t).join('
') || '- No tasks identified';

const markdownLog = `# Email Processing Log

**Generated:** ${dateStr}  
**Processing ID:** ${data.processingId}  

---

## Email Details

| Field | Value |
|---|---|
| **From** | ${data.senderName} <${data.senderEmail}> |
| **Subject** | ${data.subject} |
| **Received** | ${data.receivedDate} |

---

## AI Analysis

| Field | Result |
|---|---|
| **Category** | ${data.ai.category} |
| **Intent** | ${data.ai.intent} |
| **Urgency** | ${urgencyEmoji} ${data.ai.urgencyScore}/10 — ${data.ai.urgencyReason} |
| **Language** | ${data.ai.languageDetected} |
| **Spam Score** | ${(data.ai.spamScore * 100).toFixed(0)}% |

---

## Summary

${data.ai.summary}

---

## Draft Reply Sent

**Subject:** ${data.ai.replySubject}

\`\`\`
${data.ai.draftReply}
\`\`\`

---

## Action

✅ REPLY SENT — ${dateStr}

---

## Tasks Extracted

${taskList}

---

*Generated by AI Email Auto Responder | n8n + Ollama + Qdrant*
`;

return [{
  json: {
    ...data,
    markdownLog,
    logFilePath: '/home/node/logs/' + dateFile + '_' + data.senderEmail.replace(/[@.]/g, '_') + '.md'
  }
}];

const fs = require('fs');
const path = require('path');
const data = $input.item.json;
try {
  const dir = path.dirname(data.logFilePath);
  if (!fs.existsSync(dir)) { fs.mkdirSync(dir, { recursive: true }); }
  fs.writeFileSync(data.logFilePath, data.markdownLog, 'utf8');
  console.log('Log written:', data.logFilePath);
} catch(e) { console.error('Log write error:', e.message); }
return [{ json: { ...data, logWritten: true } }];

const data = $('Generate Markdown Log').item.json;
console.log('[SUCCESS] Processed:', data.subject, 'from', data.senderEmail);
console.log('[SUCCESS] Category:', data.ai.category, '| Urgency:', data.ai.urgencyScore);
return [{
  json: {
    status: 'success',
    completedAt: new Date().toISOString(),
    processingId: data.processingId,
    emailFrom: data.senderEmail,
    emailSubject: data.subject,
    category: data.ai.category,
    urgencyScore: data.ai.urgencyScore,
    replySent: true,
    memorySaved: true,
    logFile: data.logFilePath
  }
}];
